"""vortex_tidy --undo reverses an omw2mwse conversion: the generated files go (from the converter's manifest, each
only while it still has the manifest's hash), the original package comes back from Off\\<Mod>\\OpenMW\\ at its
original paths, the shared MWSE\\lib\\omwcompat runtime goes only when no converted mod is left in staging or Data
Files, emptied folders go, and a second --undo finds nothing to do. The converter here is a stub that writes
omw2mwse 0.2.x's real layout (checked against the real converter: loader, hosted omw\\, manifest with hashes
including the Off copies and the root game assets, runtime, metadata toml, .esp from the .omwaddon, the package
moved to Off\\<Mod>\\OpenMW\\ with an absolute relocatedFrom when it was at the mod root). Temporary folders only;
tidy never runs on live data. Python 3.9+."""
import hashlib
import json
import os
import sys
import types

import pytest

from conftest import vt

HEADER = ("-- {n}: MWSE loader generated by omw2mwse 0.2.2.\n-- Generated file: re-run omw2mwse instead of editing.\n"
          "local ok, omwcompat = pcall(require, \"omwcompat\")\nomwcompat.register({{ mod = \"{n}\" }})\n")

STUB = r'''
import hashlib, json, os, re, shutil, sys
args = sys.argv[1:]
d = os.path.realpath(next(a for a in args if not a.startswith("--")))
mode = next(a.split("=", 1)[1] for a in args if a.startswith("--convert-omwscripts="))
GAME = {"meshes", "textures", "icons", "sound", "sounds", "music", "fonts", "splash", "video", "bookart"}
sha = lambda b: hashlib.sha256(b).hexdigest()
RUNTIME = {"MWSE/lib/omwcompat.lua": b"return require('omwcompat.runtime')\n",
           "MWSE/lib/omwcompat/runtime.lua": b"return {}\n"}
with open(os.environ["STUB_LOG"], "a", encoding="utf-8") as f:
    f.write(json.dumps(args) + "\n")
dry = "--dry-run" in args
mods = []
pk = []
for base, ds, fns in os.walk(d):
    rel = os.path.relpath(base, d)
    if rel.split(os.sep)[0].lower() == "mwse":
        ds[:] = []
        continue
    if any(f.lower().endswith(".omwscripts") for f in fns):
        pk.append(base)
for src in pk:
    name = re.sub(r"[^A-Za-z0-9_\-]", "", sorted(f for f in os.listdir(src) if f.endswith(".omwscripts"))[0][:-len(".omwscripts")]) or "OpenMWMod"
    is_root = os.path.realpath(src) == d
    optout = json.loads(os.environ.get("STUB_OPTOUT", "{}"))                 # {name: the "reason" value to answer with}
    if not dry:
        optout.update(json.loads(os.environ.get("STUB_OPTOUT_REAL", "{}")))
    if name in optout:                    # omw2mwse 8367f55, author-opt-out: nothing written (no manifest either), exit 0
        r = optout[name]
        mods.append({"name": name, "source": name, "status": "ok", "verdict": "blocked", "reason": r,
                     "alerts": [{"level": "error", "code": "author-opt-out", "file": "scripts/x/main.lua", "line": 1,
                                 "message": "the mod author opted out of mwsuite conversion"}],
                     "files": {}, "plugins": [], "conflicts": [], "rewrites": [], "hardcodeLog": [], "changed": False})
        continue
    files = {}
    plan = {}
    def put(rel, data):
        plan[rel] = data
    originals = []
    alerts = []
    for base, ds, fns in os.walk(src):
        if is_root:
            ds[:] = [x for x in ds if x.lower() not in ("mwse", "off")]
        for fn in fns:
            p = os.path.join(base, fn)
            originals.append((os.path.relpath(p, src).replace(os.sep, "/"), p))
    off = "Off/%s/OpenMW" % name
    tree = "MWSE/mods/mwsuite/openmw/%s" % name
    present = {rel.lower() for rel, _ in originals}
    obsolete = {k for k, v in json.loads(os.environ.get("STUB_STATUS", "{}")).items() if v == "obsolete"}   # root plugins kept only in Off/
    for rel, p in originals:
        data = open(p, "rb").read()
        put(off + "/" + rel, data)
        top = rel.split("/")[0].lower()
        if top in GAME:
            put(rel, data)
        if rel.lower().endswith((".omwaddon", ".omwgame", ".esp", ".esm")) and "/" in rel:     # a subfolder plugin
            new = rel.rsplit(".", 1)[0] + (".esp" if rel.lower().endswith((".omwaddon", ".esp")) else ".esm")
            put("Extras/%s/%s" % (name, new), data)
            continue
        if rel.lower().endswith(".omwaddon"):
            new = rel[:-len(".omwaddon")] + ".esp"
            if new.lower() in present:
                alerts.append({"level": "warning", "code": "plugin-rename-clash",
                               "message": "%s not renamed: the package also ships %s; %s is kept only under Off/" % (rel, new, rel)})
            elif new not in obsolete:
                put(new, data)
        if "/" not in rel and rel.lower().endswith((".esp", ".esm")) and rel not in obsolete:
            put(rel, data)
        if rel.lower().endswith((".omwscripts", ".lua", ".yaml")):
            put(tree + "/omw/" + rel, data)
    put(tree + "/main.lua", os.environ.get("STUB_HEADER", "").replace("{n}", name).encode() if False else
        ("-- %s: MWSE loader generated by omw2mwse 0.2.2.\n-- Generated file: re-run omw2mwse instead of editing.\n"
         "local ok, omwcompat = pcall(require, \"omwcompat\")\nomwcompat.register({ mod = \"%s\" })\n" % (name, name)).encode())
    put(tree + "/OMW2MWSE-REPORT.md", ("report " + name + "\n").encode())
    put(name + "-metadata.toml", ("[tools.mwse]\nname = \"" + name + "\"\n").encode())
    for rel, data in RUNTIME.items():
        put(rel, data)
    plugins = []
    status = json.loads(os.environ.get("STUB_STATUS", "{}"))              # {plugin name: required|undetermined|obsolete}
    why = json.loads(os.environ.get("STUB_REASON", "{}"))
    old_optional = json.loads(os.environ.get("STUB_OLD_OPTIONAL", "{}"))   # omw2mwse 0.2.2: {name: reason}, no placement
    for rel, _p in originals:
        low = rel.lower()
        if not low.endswith((".omwaddon", ".omwgame", ".esp", ".esm")):
            continue
        kind = "esp" if low.endswith((".omwaddon", ".esp")) else "esm"
        new = rel.rsplit(".", 1)[0] + "." + kind
        if "/" not in rel and low.endswith(".omwaddon") and new.lower() in present:
            continue                                                     # the clash: the .omwaddon is not installed
        base = new.rsplit("/", 1)[-1]
        st = status.get(base, "undetermined" if "/" in rel else "required")
        place = "extras" if "/" in rel else ("off" if st == "obsolete" else "root")
        path = {"extras": "Extras/%s/%s" % (name, new), "off": "%s/%s" % (off, rel), "root": new}[place]
        if old_optional:
            plugins.append({"name": base, "source": rel, "kind": kind, "optional": base in old_optional,
                            "reason": old_optional.get(base) or "hosted Lua references getGlobalScript(\"x\")"})
        else:
            plugins.append({"name": base, "source": rel.rsplit("/", 1)[-1], "sourceRel": rel, "kind": kind,
                            "placement": place, "status": st, "path": path,
                            "reason": why.get(base) or "hosted Lua references getGlobalScript(\"x\")"})
    verdict = json.loads(os.environ.get("STUB_VERDICT", "{}")).get(name, "ready")
    if not dry:
        verdict = json.loads(os.environ.get("STUB_VERDICT_REAL", "{}")).get(name, verdict)
    if verdict == "blocked":
        alerts.append({"level": "error", "code": "blocker", "message": "requires unsupported module openmw.ui"})
    if dry:
        e = {"name": name, "source": off, "off": off, "status": "ok", "verdict": verdict, "rewrites": [],
             "conflicts": [], "files": {}, "alerts": alerts, "changed": True}
        if not os.environ.get("STUB_NO_PLUGINS"):
            e["plugins"] = plugins
        mods.append(e)
        continue
    for rel, data in plan.items():
        dst = os.path.join(d, *rel.split("/"))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        if not os.path.exists(dst) or open(dst, "rb").read() != data:
            open(dst, "wb").write(data)
    man = {"tool": "omw2mwse", "version": "0.2.2", "mod": name, "source": off, "mode": mode,
           "files": {rel: sha(data) for rel, data in sorted(plan.items())}}
    if not os.environ.get("STUB_NO_PLUGINS"):
        man["plugins"] = plugins
    mp = os.path.join(d, *tree.split("/"), "omw2mwse-manifest.json")
    open(mp, "w").write(json.dumps(man, indent=1, sort_keys=True) + "\n")
    moved = []
    for rel, p in originals:
        if is_root and (rel.split("/")[0].lower() in GAME or ("/" not in rel and rel.lower().endswith((".esp", ".esm"))
                                                                 and rel not in obsolete)):
            continue
        if os.path.realpath(p) != os.path.realpath(os.path.join(d, *(off + "/" + rel).split("/"))):
            os.remove(p)
            moved.append(rel)
    for base, ds, fns in os.walk(src, topdown=False):
        if not is_root and not os.listdir(base):
            os.rmdir(base)
    parent = os.path.dirname(src)
    while not is_root and os.path.realpath(parent) != d and not os.listdir(parent):
        os.rmdir(parent)
        parent = os.path.dirname(parent)
    entry = {"name": name, "source": off, "off": off, "status": "ok", "verdict": verdict, "rewrites": [],
             "conflicts": [], "files": {}, "alerts": alerts, "changed": True}
    if not os.environ.get("STUB_NO_PLUGINS") and not os.environ.get("STUB_NO_PLUGINS_IN_JSON"):
        entry["plugins"] = plugins
    if moved:
        entry["relocatedFrom"] = src if is_root else os.path.relpath(src, d).replace(os.sep, "/")
        entry["relocated"] = moved
    mods.append(entry)
print(json.dumps({"tool": "omw2mwse", "version": "0.2.2", "command": "convert", "mode": mode, "dir": d,
                  "dryRun": dry, "changed": True, "exitCode": 0, "alerts": [], "mods": mods}))
'''


def put(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    (path.write_bytes if isinstance(data, bytes) else path.write_text)(data)


def root_mod(staging, name):
    """An OpenMW-only mod with its package at the mod root (meshes stay put when converted)."""
    mod = staging / f"{name}-1-0"
    put(mod / f"{name}.omwscripts", f"GLOBAL: scripts/{name}/g.lua\n")
    put(mod / "scripts" / name / "g.lua", f"return '{name}'\n")
    put(mod / "l10n" / name / "en.yaml", "a: b\n")
    put(mod / "meshes" / "x" / f"{name}.nif", b"nif")
    put(mod / f"{name}.omwaddon", b"TES3")
    put(mod / "readme.txt", "hi\n")
    return mod


def legacy_mod(staging, name):
    """A package earlier tidy runs set aside at Off\\OpenMW\\<name>\\, with a mesh converted to the root."""
    mod = staging / f"{name}-1-0"
    pk = mod / "Off" / "OpenMW" / name
    put(pk / f"{name}.omwscripts", f"GLOBAL: scripts/{name}/g.lua\n")
    put(pk / "scripts" / name / "g.lua", f"return '{name}'\n")
    put(pk / "meshes" / f"{name}.nif", b"nif")
    return mod


def snap(root):
    files, dirs = {}, set()
    for base, ds, fns in os.walk(str(root)):
        for d in ds:
            dirs.add(os.path.relpath(os.path.join(base, d), str(root)))
        for fn in fns:
            p = os.path.join(base, fn)
            files[os.path.relpath(p, str(root))] = hashlib.sha256(open(p, "rb").read()).hexdigest()
    return files, dirs


@pytest.fixture
def env(tmp_path, monkeypatch):
    game = tmp_path / "game"
    (game / "Data Files").mkdir(parents=True)
    staging = tmp_path / "staging"
    staging.mkdir()
    home = tmp_path / "tools-home"
    (home / "tools").mkdir(parents=True)
    (home / "tools" / "omw2mwse.py").write_text(STUB)
    monkeypatch.setenv("PATH", str(tmp_path / "empty-path"))
    monkeypatch.setattr(vt, "CONVERTER_HOME", str(home))
    monkeypatch.setattr(vt, "CONVERTER", dict(vt.CONVERTER))
    monkeypatch.setattr(vt, "interpreter_version", lambda cmd: (3, 11))       # the stub runs on any Python
    monkeypatch.setattr(vt, "HERE", str(game))
    monkeypatch.setattr(vt, "CORE_MISSING", {})
    monkeypatch.setattr(vt, "vortex_info", lambda d: {})                   # never reads the real Vortex state
    monkeypatch.setenv("STUB_LOG", str(tmp_path / "calls.jsonl"))
    monkeypatch.setattr(vt, "JOURNAL", str(tmp_path / "journal.jsonl"))
    monkeypatch.setattr(vt, "PLAN", str(tmp_path / "vortex_tidy_plan.txt"))
    monkeypatch.setattr(vt, "AUDIT_ROOT", str(tmp_path / "audit"))
    monkeypatch.setattr(vt, "BLACKLIST_FILE", str(tmp_path / "bl.txt"))
    for d in (vt.NOTES, vt.REVIEW, vt.CONVERTED, vt.CONVERT):
        d.clear()

    def apply(*only):
        extra = ["--only", *only] if only else []
        vt.NOTES.clear()                                                   # one process per run in real life
        monkeypatch.setattr(vt.sys, "argv", ["vortex_tidy.py", "--staging", str(staging), "--no-lua", "--no-assets",
                                             *extra])
        assert vt.main() == 0
        monkeypatch.setattr(vt.sys, "argv", ["vortex_tidy.py", "--staging", str(staging), "--no-lua", "--no-assets",
                                             "--apply", "--yes", *extra])
        vt.NOTES.clear()
        assert vt.main() == 0

    def journal():
        return [json.loads(x) for x in open(vt.JOURNAL, encoding="utf-8") if x.strip()]
    def calls():
        log = tmp_path / "calls.jsonl"
        return [json.loads(x) for x in log.read_text().splitlines()] if log.exists() else []
    return types.SimpleNamespace(staging=staging, game=game, apply=apply, journal=journal, tmp=tmp_path,
                                 calls=calls, mp=monkeypatch)


def test_root_package_is_converted_then_undone_exactly(env, capsys):
    mod = root_mod(env.staging, "Foo")
    before = snap(mod)
    env.apply()
    after, _ = snap(mod)
    assert "Foo.esp" in after and "Off/Foo/OpenMW/Foo.omwaddon".replace("/", os.sep) in after
    assert "Foo.omwaddon" not in after and "readme.txt" not in after       # moved to Off by the converter
    (conv,) = [o for o in env.journal() if "omw_convert" in o]
    assert conv["name"] == "Foo" and conv["from"] == "" and conv["off"] == "Off/Foo/OpenMW"
    assert conv["files"] and sorted(conv["relocated"])[0] == "Foo.omwaddon"
    capsys.readouterr()
    assert vt.undo() == 0
    out = capsys.readouterr()
    assert snap(mod) == before                                             # files, content and folders as before
    assert "WARNING" not in out.err and "omw2mwse conversions undone: 1 mod(s)" in out.out
    assert out.out.count("\n") <= 6                                         # quiet


def test_package_set_aside_under_off_goes_back_there(env):
    mod = legacy_mod(env.staging, "Bar")
    before = snap(mod)
    env.apply()
    after, _ = snap(mod)
    assert os.path.join("Off", "Bar", "OpenMW", "Bar.omwscripts") in after
    assert os.path.join("Off", "OpenMW", "Bar", "Bar.omwscripts") not in after and "meshes\\Bar.nif".replace("\\", os.sep) in after
    assert vt.undo() == 0
    assert snap(mod) == before                                             # the root mesh copy is gone too


def test_a_second_undo_changes_nothing(env, capsys):
    mod = root_mod(env.staging, "Foo")
    before = snap(mod)
    env.apply()
    assert vt.undo() == 0
    capsys.readouterr()
    assert vt.undo() == 1
    assert "Nothing to undo" in capsys.readouterr().out
    assert snap(mod) == before


def test_an_edited_generated_file_stays_with_one_warning_and_the_rest_is_undone(env, capsys):
    mod = root_mod(env.staging, "Foo")
    before = snap(mod)
    env.apply()
    loader = mod / "MWSE" / "mods" / "mwsuite" / "openmw" / "Foo" / "main.lua"
    edited = loader.read_text() + "-- my change\n"
    loader.write_text(edited)
    assert vt.undo() == 0
    err = capsys.readouterr().err
    assert err.count("WARNING") == 1 and "main.lua" in err and "changed since omw2mwse wrote it" in err
    assert loader.read_text() == edited                                    # kept, as edited
    after, _ = snap(mod)
    assert (mod / "MWSE" / "mods" / "mwsuite" / "openmw" / "Foo" / "omw2mwse-manifest.json").exists()   # still owns it
    assert (mod / "MWSE" / "lib" / "omwcompat.lua").exists()               # a converted mod is left: runtime stays
    assert not (mod / "Foo.esp").exists() and not (mod / "Off").exists()
    for rel, h in before[0].items():                                       # every original is back, byte for byte
        assert after[rel] == h, rel
    assert vt.undo() == 1                                                  # nothing more to undo: still kept


def test_two_converted_mods_share_the_runtime_and_both_go_when_both_are_undone(env):
    a, b = root_mod(env.staging, "Aaa"), root_mod(env.staging, "Bbb")
    before = (snap(a), snap(b))
    env.apply()
    assert (a / "MWSE" / "lib" / "omwcompat.lua").exists() and (b / "MWSE" / "lib" / "omwcompat.lua").exists()
    assert vt.undo() == 0
    assert (snap(a), snap(b)) == before                                    # no runtime left in either


def test_runtime_stays_while_another_converted_mod_is_left_in_staging(env):
    a, b = root_mod(env.staging, "Aaa"), root_mod(env.staging, "Bbb")
    env.apply("Bbb*")                                                      # B converted by an earlier run
    os.remove(vt.JOURNAL)                                                  # that run's journal is not this undo's
    before_a = snap(a)
    env.apply("Aaa*")
    assert vt.undo() == 0
    after_a, _ = snap(a)
    assert (a / "MWSE" / "lib" / "omwcompat.lua").exists()                 # B still needs it
    assert not (a / "MWSE" / "mods").exists() and not (a / "Foo.esp").exists()
    left = {k: v for k, v in after_a.items() if not k.startswith("MWSE" + os.sep + "lib")}
    assert left == before_a[0]
    assert (b / "MWSE" / "mods" / "mwsuite" / "openmw" / "Bbb" / "main.lua").exists()   # B untouched
    assert (b / "Off" / "Bbb" / "OpenMW" / "Bbb.omwscripts").exists()


def test_runtime_stays_while_a_converted_mod_is_left_in_data_files(env):
    a = root_mod(env.staging, "Aaa")
    other = env.game / "Data Files" / "MWSE" / "mods" / "mwsuite" / "openmw" / "Other"
    put(other / "main.lua", "-- Other: MWSE loader generated by omw2mwse 0.2.2.\n")
    put(env.game / "Data Files" / "MWSE" / "mods" / "mwsuite" / "openmw" / "Aaa" / "main.lua",
        "-- Aaa: MWSE loader generated by omw2mwse 0.2.2.\n")                # A's own deployed copy: doesn't count
    env.apply()
    assert vt.undo() == 0
    assert (a / "MWSE" / "lib" / "omwcompat.lua").exists()
    other.joinpath("main.lua").unlink()                                    # nothing left in Data Files now
    env.apply()                                                            # converts A again (undo restored it)
    assert vt.undo() == 0
    assert not (a / "MWSE").exists() or not (a / "MWSE" / "lib" / "omwcompat.lua").exists()


def test_a_file_already_at_an_original_path_is_never_overwritten(env, capsys):
    mod = root_mod(env.staging, "Foo")
    env.apply()
    (mod / "readme.txt").write_text("a newer readme\n")                    # in the way of the original
    assert vt.undo() == 0
    err = capsys.readouterr().err
    assert err.count("WARNING") == 1 and "differs" in err
    assert (mod / "readme.txt").read_text() == "a newer readme\n"
    assert (mod / "Off" / "Foo" / "OpenMW" / "readme.txt").read_text() == "hi\n"   # the original is kept in Off


def test_user_files_beside_the_conversion_are_never_touched(env):
    mod = root_mod(env.staging, "Foo")
    env.apply()
    put(mod / "MWSE" / "mods" / "Mine" / "main.lua", "print('mine')\n")
    put(mod / "MWSE" / "config" / "omwcompat_Foo.json", "{}")              # the game's settings: not in the manifest
    put(mod / "notes.txt", "mine\n")
    assert vt.undo() == 0
    assert (mod / "MWSE" / "mods" / "Mine" / "main.lua").exists() and (mod / "notes.txt").exists()
    assert (mod / "MWSE" / "config" / "omwcompat_Foo.json").exists()
    assert not (mod / "MWSE" / "mods" / "mwsuite").exists()


def test_without_the_manifest_the_journaled_copy_is_used(env):
    mod = root_mod(env.staging, "Foo")
    before = snap(mod)
    env.apply()
    os.remove(mod / "MWSE" / "mods" / "mwsuite" / "openmw" / "Foo" / "omw2mwse-manifest.json")
    assert vt.undo() == 0
    assert snap(mod) == before


def test_with_no_record_at_all_the_marker_verified_tree_goes(env):
    mod = root_mod(env.staging, "Foo")
    env.apply()
    os.remove(mod / "MWSE" / "mods" / "mwsuite" / "openmw" / "Foo" / "omw2mwse-manifest.json")
    put(mod / "MWSE" / "config" / "omwcompat_Foo.json", "{}")
    (conv,) = [o for o in env.journal() if "omw_convert" in o]
    conv["files"] = {}
    cstate = {"mods": 0, "removed": 0, "restored": 0, "defer": [], "names": set(), "staging": str(env.staging)}
    assert vt.undo_conversion(conv, str(env.staging), cstate)
    vt.finish_conversions(cstate)
    assert (mod / "Foo.omwaddon").exists() and (mod / "readme.txt").exists()          # originals back
    assert (mod / "Foo.esp").exists() and (mod / "Foo-metadata.toml").exists()        # no hash: not verifiable
    assert not (mod / "MWSE").exists()                                                # tree, config, runtime


def test_a_marker_less_folder_is_not_deleted_without_a_record(env):
    mod = root_mod(env.staging, "Foo")
    env.apply()
    tree = mod / "MWSE" / "mods" / "mwsuite" / "openmw" / "Foo"
    os.remove(tree / "omw2mwse-manifest.json")
    put(tree / "main.lua", "print('a hand port')\n")                       # loader no longer says omw2mwse
    for p in list(tree.rglob("*")):
        if p.is_file() and p.name != "main.lua":
            p.unlink()
    (conv,) = [o for o in env.journal() if "omw_convert" in o]
    conv["files"] = {}
    cstate = {"mods": 0, "removed": 0, "restored": 0, "defer": [], "names": set(), "staging": str(env.staging)}
    assert vt.undo_conversion(conv, str(env.staging), cstate)
    assert (tree / "main.lua").read_text() == "print('a hand port')\n"


def test_manifest_paths_that_climb_out_of_the_mod_are_ignored(env):
    mod = root_mod(env.staging, "Foo")
    victim = env.tmp / "victim.txt"
    victim.write_text("x")
    op = {"omw_convert": str(mod), "name": "Foo", "from": "", "off": "Off/Foo/OpenMW",
          "tree": "MWSE/mods/mwsuite/openmw/Foo", "files": {"../../victim.txt": hashlib.sha256(b"x").hexdigest()}}
    cstate = {"mods": 0, "removed": 0, "restored": 0, "defer": [], "names": set(), "staging": str(env.staging)}
    assert vt.undo_conversion(op, str(env.staging), cstate)
    assert victim.exists()


def test_the_record_normalises_the_converters_paths(env):
    mod = root_mod(env.staging, "Foo")
    e = {"name": "Foo", "source": "Off/Foo/OpenMW", "off": "Off/Foo/OpenMW", "relocatedFrom": str(mod),
         "relocated": ["b", "a"]}
    op = vt.conversion_op(str(mod), e, "hardcode")
    assert op["from"] == "" and op["off"] == "Off/Foo/OpenMW" and op["relocated"] == ["a", "b"]
    e["relocatedFrom"] = "Off/OpenMW/Foo"
    assert vt.conversion_op(str(mod), e, "normal")["from"] == "Off/OpenMW/Foo"
    del e["relocatedFrom"]
    assert vt.conversion_op(str(mod), e, "normal")["from"] == "Off/Foo/OpenMW"      # not moved: nothing to put back


def test_one_undo_reverses_the_moves_and_the_conversion_of_the_same_apply(env):
    foo = root_mod(env.staging, "Foo")
    plain = env.staging / "Plain-1-0"
    put(plain / "Plain.esp", b"TES3")
    put(plain / "notes.txt", "n\n")
    before = (snap(foo), snap(plain))
    env.apply()
    assert not (plain / "notes.txt").exists()                              # tidy's usual move happened
    ids = {r["apply"] for r in env.journal() if "run" in r}
    assert len(ids) == 1                                                   # one id: one --undo undoes them all
    assert vt.undo() == 0
    assert (snap(foo), snap(plain)) == before


