def test_the_package_is_named_like_the_converter_names_it_not_after_the_vortex_folder(env):
    """Off\\<plugin name>\\OpenMW: the first .omwscripts' stem (sorted), cleaned the way omw2mwse cleans it, never
    the Vortex folder's name. The converter then finds it already at its canonical place and moves nothing."""
    mod = env.staging / "Wild Attacks-54448-1-9"
    put(mod / "zeta.omwscripts", "GLOBAL: scripts/wan/g.lua\n")
    put(mod / "my plugin (v2)!.omwscripts", "GLOBAL: scripts/wan/g.lua\n")
    put(mod / "scripts" / "wan" / "g.lua", "return 1\n")
    put(mod / "meshes" / "x.nif", b"nif")
    put(mod / "Docs" / "manual.txt", "hi\n")
    put(mod / "Screenshots" / "s.png", b"png")
    before = snap(mod)
    env.mp.setattr(vt, "CONVERTER_HOME", str(env.tmp / "nowhere"))                 # step 1: no converter
    env.apply()
    after, _ = snap(mod)
    assert sorted({k.split(os.sep)[0] for k in after}) == ["Off"]
    pk = os.path.join("Off", "mypluginv2", "OpenMW")                                  # "my plugin (v2)!" cleaned
    assert os.path.join(pk, "zeta.omwscripts") in after and os.path.join(pk, "Docs", "manual.txt") in after
    assert os.path.join(pk, "Screenshots", "s.png") in after
    env.mp.setattr(vt, "CONVERTER_HOME", str(env.tmp / "tools-home"))              # step 2: the converter is back
    env.apply()
    again, _ = snap(mod)
    assert os.path.join(pk, "zeta.omwscripts") in again                              # relocated nothing; Docs stayed in
    assert os.path.join(pk, "Docs", "manual.txt") in again
    assert vt.undo() == 0
    assert vt.undo() == 0
    assert snap(mod) == before


def test_name_when_the_scripts_are_not_at_the_root(env):
    d = env.tmp / "pkg"
