def test_a_package_an_earlier_tidy_run_put_in_off_openmw_is_moved_idempotently_and_undoes_exactly(env, capsys):
    mod = legacy_mod(env.staging, "Bar")                                             # Off\OpenMW\Bar\ + a root mesh
